#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define MaaDurga ios_base::sync_with_stdio(false); cin.tie(NULL);

ll help(ll k1, ll k2, ll n, const vector<ll>&p){
    ll i1 = k1;
    ll i2 = k1 + 2 * k2;
    ll i3 = 3 * n-2 * k1 - k2;
    
    return (2 * p[i1] + p[i2]+ 3*p[i3]);
}

int main() {
	MaaDurga
	
	ll t;
	cin >> t;
	
	while(t--)
	{
	    ll n;
	    cin >> n;
	    
	    vector<ll> arr(3*n);
	    for(int i=0; i<3*n; i++) cin >> arr[i];
	    
	    sort(arr.rbegin(), arr.rend());
	    
	    vector<ll> p(3*n+1, 0);
	    for(int i=0; i < n*3 ; i++){
	        p[i + 1] = p[i]  + arr[i];
	    }
	    
	    ll maxi  = 0;
	    for(ll k1 = 0; k1<=n; k1++){
	        ll l = 0, h = n - k1;
	        while(h - l >= 3){
	            ll mid1 = l + (h - l)/3;
	            ll mid2 = h - (h - l)/3;
	            
	            if(help(k1, mid1, n, p) < help(k1, mid2, n, p)) l = mid1;
	            else h = mid2;
	        }
	        for(ll k2 = l; k2 <= h; k2++){
	            ll cnt = help(k1, k2, n, p);
	            if(cnt > maxi) maxi = cnt;
	 
	        }
	    }
	    cout << maxi << endl;
	}
	return 0;

}
